// PHP 8.5.12 mb_convert_encoding mappings to UTF-32BE. Zero entries in delta tables keep the base mapping.
import { inflateRawSync } from 'node:zlib';

export type LegacyDetectionTable = keyof typeof data;

const tables = new Map<LegacyDetectionTable, Buffer>();

export function legacyDetectionCodePoint(name: LegacyDetectionTable, index: number): number {
  let table = tables.get(name);
  if (!table) {
    table = inflateRawSync(Buffer.from(data[name], 'base64'));
    tables.set(name, table);
  }
  return WIDE_TABLES.has(name) ? table.readUInt32BE(index * 4) : table.readUInt16BE(index * 2);
}

const WIDE_TABLES = new Set<LegacyDetectionTable>([
  'jis0213Plane1',
  'jis0213Plane2',
  'sjisMac',
  'sjisDocomo',
  'sjisKddi',
  'sjisSoftbank',
  'softbankEscape',
  'iso2022JpKddi',
]);

// Wide mappings store JIS combining pairs or an index into the variable-length sequences.
export function appendLegacyMapping(codes: number[], code: number, bad: number): void {
  if (code >= 0x80_00_00_00) codes.push((code >>> 16) & 0x7f_ff, code & 0xff_ff);
  else if (code >= 0x40_00_00_00) codes.push(...sequences[code - 0x40_00_00_00]);
  else codes.push(code === 0xff_fd ? bad : code);
}

